// Проверяем, что context.item и context.item.data реально есть
if (!context.item || !collections[/* Supabase CurrentGame */ '4ecf67f7-be96-450b-8193-ed068f2dd67a']?.['data']) return '';

// Берём цвета и угол
const color1 = collections[/* Supabase CurrentGame */ '4ecf67f7-be96-450b-8193-ed068f2dd67a']?.['data']?.[0]?.['gradient_color_1'];
const color2 = collections[/* Supabase CurrentGame */ '4ecf67f7-be96-450b-8193-ed068f2dd67a']?.['data']?.[0]?.['gradient_color_2'];
const angle = collections[/* Supabase CurrentGame */ '4ecf67f7-be96-450b-8193-ed068f2dd67a']?.['data']?.[0]?.['gradient_angle'] ?? 45; // если нет угла, ставим 45°

if (!color1 || !color2) {
    // fallback, если нет цветов
    return 'linear-gradient(45deg, #232526, #414345)';
}

// Приводим к строке и убираем лишние кавычки/пробелы
const safeColor1 = String(color1).replace(/['"]/g, '').trim();
const safeColor2 = String(color2).replace(/['"]/g, '').trim();
const safeAngle = Number(angle); // на всякий случай

// Возвращаем готовый CSS
return 'linear-gradient(' + safeAngle + 'deg, ' + safeColor1 + ', ' + safeColor2 + ')';

